    mut out: *mut c_uchar,
    mut outlen: *mut c_int,
    mut in_0: *const c_uchar,
    mut inlen: *mut c_int,
    mut quoteChar: c_int,
) -> c_int {
    let out_cap = if out.is_null() || outlen.is_null() || inlen.is_null() || in_0.is_null() {
        return -(1 as c_int);
    } else {
        *outlen as usize
    };
    let in_cap = *inlen as usize;

    // SAFETY: null pointers are rejected above; lengths come from *outlen/*inlen and are
    // stable in this function; caller provides valid buffers for those lengths, and we create
    // exactly one mutable view for `out` plus one shared view for `in_0`, so no overlapping
    // Rust references are introduced here.
    let out_buf = unsafe { ::core::slice::from_raw_parts_mut(out, out_cap) };
    // SAFETY: null pointers are rejected above; length comes from *inlen and is stable in this
    // function; caller provides a valid readable input buffer for that length, and this shared
    // view does not alias the mutable output view as a Rust reference.
    let in_buf = unsafe { ::core::slice::from_raw_parts(in_0, in_cap) };

    let mut processed_idx: usize = 0;
    let mut in_idx: usize = 0;
    let mut out_idx: usize = 0;
    let mut c: c_uint = 0;
    let mut d: c_uint = 0;
    let mut trailing: c_int = 0;
    let quote_char_u = quoteChar as c_uint;

    while in_idx < in_buf.len() {
        d = in_buf[in_idx] as c_uint;
        in_idx += 1;

        if d < 0x80 as c_uint {
            c = d;
            trailing = 0 as c_int;
        } else if d < 0xc0 as c_uint {
            *outlen = out_idx as c_int;
            *inlen = processed_idx as c_int;
            return -(2 as c_int);
        } else if d < 0xe0 as c_uint {
            c = d & 0x1f as c_uint;
            trailing = 1 as c_int;
        } else if d < 0xf0 as c_uint {
            c = d & 0xf as c_uint;
            trailing = 2 as c_int;
        } else if d < 0xf8 as c_uint {
            c = d & 0x7 as c_uint;
            trailing = 3 as c_int;
        } else {
            *outlen = out_idx as c_int;
            *inlen = processed_idx as c_int;
            return -(2 as c_int);
        }

        if (in_buf.len() - in_idx) < trailing as usize {
            break;
        }

        while trailing != 0 {
            d = in_buf[in_idx] as c_uint;
            in_idx += 1;
            trailing -= 1;

            if d & 0xc0 as c_uint != 0x80 as c_uint {
                *outlen = out_idx as c_int;
                *inlen = processed_idx as c_int;
                return -(2 as c_int);
            }
            c <<= 6 as c_int;
            c |= d & 0x3f as c_uint;
        }

        if c < 0x80 as c_uint
            && c != quote_char_u
            && c != '&' as i32 as c_uint
            && c != '<' as i32 as c_uint
            && c != '>' as i32 as c_uint
        {
            if out_idx >= out_buf.len() {
                break;
            }
            out_buf[out_idx] = c as c_uchar;
            out_idx += 1;
        } else {
            let mut ent: *const htmlEntityDesc = ::core::ptr::null::<htmlEntityDesc>();
            let entity_bytes: &[u8];
            let mut nbuf: [u8; 16] = [0; 16];
            let len: usize;

            ent = htmlEntityValueLookup(c);
            if ent.is_null() {
                let mut pos = 0usize;
                nbuf[pos] = b'#';
                pos += 1;

                let mut val = c;
                let mut digits_rev = [0u8; 10];
                let mut ndigits = 0usize;
                loop {
                    digits_rev[ndigits] = b'0' + (val % 10) as u8;
                    ndigits += 1;
                    val /= 10;
                    if val == 0 {
                        break;
                    }
                }
                while ndigits != 0 {
                    ndigits -= 1;
                    nbuf[pos] = digits_rev[ndigits];
                    pos += 1;
                }
                entity_bytes = &nbuf[..pos];
                len = pos;
            } else {
                let cp = (*ent).name as *const u8;
                let mut name_len = 0usize;
