                    // the entity table; we scan bytewise until its terminating NUL without
                    // creating a CStr in this hot function.
                    let b = unsafe { *cp.add(name_len) };
                    if b == 0 {
                        break;
                    }
                    name_len += 1;
                }
                // SAFETY: same justification as above; `name_len` was computed by scanning the
                // same NUL-terminated string, so this range is valid and excludes the terminator.
                entity_bytes = unsafe { ::core::slice::from_raw_parts(cp, name_len) };
                len = name_len;
            }

            if (out_buf.len() - out_idx) < len + 2 {
                break;
            }

            out_buf[out_idx] = b'&';
            out_idx += 1;
            out_buf[out_idx..out_idx + len].copy_from_slice(entity_bytes);
            out_idx += len;
            out_buf[out_idx] = b';';
            out_idx += 1;
        }

        processed_idx = in_idx;
    }

    *outlen = out_idx as c_int;
    *inlen = processed_idx as c_int;
    0 as c_int
